describe("doctests of sympy.integrals.meijerint", () => {
  it("r[0]", () => {
    const s = new Sym('s');
    expect(sympyStr(mul(Rational.of(1n, 4n, { gcd: 1n }), s, pow(pi, Rational.of(-1n, 2n, { gcd: 1n }))))).toBe('s/(4*sqrt(pi))');
  });
  it("r[1]", () => {
    const [t, s] = symbols('t s');
    expect(sympyStr(meijerg([], [], [Rational.of(-1n, 2n, { gcd: 1n }), Rational.of(0n, 1n, { gcd: 1n })], [], mul(Rational.of(1n, 4n, { gcd: 1n }), t, pow(s, Rational.of(2n, 1n, { gcd: 1n })))))).toBe('meijerg(((), ()), ((-1/2, 0), ()), s**2*t/4)');
  });
  it("r[2]", () => {
    const [m, t] = symbols('m t');
    expect(sympyStr(meijerg([], [], [mul(Rational.of(1n, 2n, { gcd: 1n }), m)], [mul(Rational.of(-1n, 2n, { gcd: 1n }), m)], mul(Rational.of(1n, 4n, { gcd: 1n }), t)))).toBe('meijerg(((), ()), ((m/2,), (-m/2,)), t/4)');
  });
  // the arguments do not type-check against the public API
  //   meijerint_definite(exp(-x**2), x, -oo, oo)
  //   => (sqrt(pi), True)
  it.todo("meijerint_definite(exp(-x**2), x, -oo, oo)");
  it("meijerint_indefinite(sin(x), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(meijerintIndefinite(fn('sin', [x], { evaluate: false }), x))).toBe('-cos(x)');
  });
  it("meijerint_inversion(1/x, x, t)", () => {
    const [x, t] = symbols('x t');
    expect(sympyStr(meijerintInversion(pow(x, Rational.of(-1n, 1n, { gcd: 1n })), x, t))).toBe('Heaviside(t)');
  });
});

